// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C(); }

    function testFuzz_property(uint64 ts, uint64 roll, uint256 amount, address actor) public {
        vm.assume(amount == 10); // admissible ticket price
        vm.assume(actor != address(0) && actor != address(c) && actor != address(this));

        // seed the pot first so a win pays out more than the fee
        vm.deal(address(this), 10);
        c.play{value: 10}();

        vm.deal(actor, amount);
        vm.warp(ts);
        vm.roll(roll);
        vm.prank(actor);
        c.play{value: amount}();

        uint256 random = uint256(keccak256(abi.encodePacked(ts, roll))) % 2;
        if (random == 0) {
            // General rule: after any winning play, the pot is fully emptied.
            assertTrue(address(c).balance == 0, "pot not emptied after win");
        } else {
            // No win: pot grows by the ticket, contract holds exactly pot.
            assertTrue(address(c).balance == c.pot(), "balance must equal pot");
        }
    }
}

