pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }

    function testFuzz_property(uint256 ts, address player) public {
        // admissible domain: player is a plain EOA (accepts ETH payouts), distinct from c
        vm.assume(player.code.length == 0);
        vm.assume(player != address(c));
        vm.assume(player != address(this));

        // find a timestamp (near the fuzzed one) for which the contract's RNG yields a WIN (random == 0)
        uint256 diff = block.difficulty;
        uint256 chosen = ts;
        bool win = false;
        for (uint256 i = 0; i < 512; i++) {
            uint256 t = ts + i;
            if (uint256(keccak256(abi.encodePacked(t, diff))) % 2 == 0) {
                chosen = t;
                win = true;
                break;
            }
        }
        vm.assume(win);
        vm.warp(chosen);

        // player buys exactly one ticket; on a win the pot must be fully emptied
        vm.deal(player, 10);
        vm.prank(player);
        c.play{value: 10}();

        // GENERAL RULE: after any winning play, pot is reset to 0.
        // The mutant leaves FEE_AMOUNT (1 wei) in the pot after every win.
        assertTrue(c.pot() == 0);
    }
}

