contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 amount, uint256 seed, address actor) public {
        // admissible domain: a valid ticket purchase by an ordinary EOA
        vm.assume(amount == 10); // ticket price is fixed by the contract
        vm.assume(actor != address(0) && actor != address(c) && actor.code.length == 0);
        vm.warp(seed); // seed the fuzzer-controlled randomness source
        vm.deal(actor, 10);
        vm.prank(actor);
        c.play{value: 10}();
        // Rule: pot is always a whole number of tickets (0 or 10*k) after any play;
        // the mutant leaves 9 (or 10k-1) after a winning play.
        assertTrue(c.pot() % 10 == 0);
    }
}

